import sys, traceback, itertools, random
sys.path.insert(0, '/dateutil')
from dateutil import parser as P

orig = P.parser._parse
found = {}

def patched(self, timestr, *a, **kw):
    try:
        return orig(self, timestr, *a, **kw)
    except IndexError:
        tb = traceback.format_exc()
        # find the deepest frame in parser.py
        lines = [l for l in tb.splitlines() if 'parser.py' in l]
        key = lines[-1].strip() if lines else tb
        found.setdefault(key, []).append((timestr, kw))
        raise

P.parser._parse = patched

# candidate strings
alphabet = list("0123456789:./-+ ,;'hmsatpZ()T")
random.seed(0)
cands = []
# exhaustive short strings over a small alphabet
small = list("0123456789:.- ")
for n in (1,2,3,4):
    for t in itertools.product(small, repeat=n):
        cands.append("".join(t))
for n in (5,6,7,8):
    for _ in range(60000):
        cands.append("".join(random.choice(alphabet) for _ in range(n)))
# also some structured ones
for a in ["1","12","123","1234","12345","123456","12345678","123456789012"]:
    for b in ["", " ", ":", "h", "m", "s", " h", " m", " s", " h ", " m ", " h 3", " m 30", " s 30", ":", ":30", ":30:40", "T", "-", "/", ".", ","]:
        cands.append(a+b)

for c in cands:
    for kw in ({}, {'fuzzy': True}):
        try:
            patched(P.DEFAULTPARSER, c, **kw)
        except Exception:
            pass

for k, v in sorted(found.items(), key=lambda kv: -len(kv[1])):
    print(len(v), k)
    for s in v[:5]:
        print("     ", repr(s))
